import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'
import posthog from 'posthog-js'

import { FEATURE_FLAGS } from 'lib/constants'
import { FeatureFlagsSet, featureFlagLogic } from 'lib/logic/featureFlagLogic'

import { TraceViewChoice } from './types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface traceViewPreferenceLogicValues {
    featureFlags: FeatureFlagsSet // featureFlagLogic
    activeView: TraceViewChoice
    isSwitchAvailable: boolean
    preferredView: TraceViewChoice
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface traceViewPreferenceLogicActions {
    switchView: (view: TraceViewChoice) => {
        view: TraceViewChoice
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface traceViewPreferenceLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        isSwitchAvailable: (featureFlags: FeatureFlagsSet) => boolean
        activeView: (isSwitchAvailable: boolean, preferredView: TraceViewChoice) => TraceViewChoice
    }
}

export type traceViewPreferenceLogicType = MakeLogicType<
    traceViewPreferenceLogicValues,
    traceViewPreferenceLogicActions,
    Record<string, any>,
    traceViewPreferenceLogicMeta
>

export const traceViewPreferenceLogic = kea<traceViewPreferenceLogicType>([
    path(['products', 'ai_observability', 'frontend', 'redesign', 'trace', 'traceViewPreferenceLogic']),
    connect(() => ({ values: [featureFlagLogic, ['featureFlags']] })),
    actions({
        switchView: (view: TraceViewChoice) => ({ view }),
    }),
    reducers({
        preferredView: [
            'new' as TraceViewChoice,
            // The key is fixed so that moving this logic does not reset the stored choice.
            { persist: true, storageKey: 'ai_observability.trace_view_choice' },
            {
                switchView: (_, { view }) => view,
            },
        ],
    }),
    selectors({
        isSwitchAvailable: [
            (s) => [s.featureFlags],
            (featureFlags: FeatureFlagsSet): boolean => !!featureFlags[FEATURE_FLAGS.AI_OBSERVABILITY_TRACE_REDESIGN],
        ],
        activeView: [
            (s) => [s.isSwitchAvailable, s.preferredView],
            (isSwitchAvailable: boolean, preferredView: TraceViewChoice): TraceViewChoice =>
                isSwitchAvailable ? preferredView : 'legacy',
        ],
    }),
    listeners(() => ({
        switchView: ({ view }) => {
            // A rename of this event or of the `to` property breaks every insight that filters on them.
            posthog.capture('llma trace view switched', { to: view })
        },
    })),
])
